use spore_core::creature_skin_cube_walk_v1::{tables,walk};use std::io::Write;
fn main(){let t=tables();let mut out=Vec::new();if std::env::args().nth(1).as_deref()==Some("--tables"){for x in t.masks{out.extend(x.to_le_bytes())}out.extend(t.orientation);out.extend(t.endpoints);for group in t.successor{for entry in group{out.extend(entry)}}for i in 0..8u32{out.extend([((i>>0)&1) as u8,((i>>1)&1) as u8,((i>>2)&1) as u8,0]);}}else{for case in 0..258 {let class=if case<256{case as u8}else if case==256{1}else{3};let mut logs=Vec::new();let mut tris=Vec::new();let r=walk(&t,0xaaffffff,class,&mut tris,|key,p|{logs.push([key[0],key[1],p[0],p[1]]);if case==257&&logs.len()==2{None}else{Some(if case==256{3}else{logs.len() as u32})}});assert!(logs.len()<=24&&tris.len()<=24);for v in [u32::from(r.is_ok()),logs.len() as u32,tris.len() as u32]{out.extend(v.to_le_bytes())}for i in 0..24{for x in logs.get(i).copied().unwrap_or([0;4]){out.extend(x.to_le_bytes())}}for i in 0..24{for x in tris.get(i).copied().unwrap_or([0;3]){out.extend(x.to_le_bytes())}}}}std::io::stdout().write_all(&out).unwrap();}
